const policies = [
  'FIFO',
  'LRU',
  'LFU',
  'NRU',
  'AGING',
  'CLOCK',
  'ECLOCK',
  'WSCLOCK',
  'RANDOM',
  'OPT',
];
  int page = 256, frames = 4, tlb = 4, sets = 1, tick = 0, tau = 8, seed = 1;
  String policy = 'FIFO', scope = 'GLOBAL', asid = 'OFF';
  String description() =>
